from pathlib import Path
import json,hashlib,subprocess,difflib
w=Path(__file__).resolve().parent;s=w.parent
sha=lambda p:hashlib.sha256(p.read_bytes()).hexdigest()
receipt=json.loads((w/'link-2/receipt.json').read_text())
assert all(sha(Path(p))==h for p,h in receipt['frozen_inputs'].items())
compat=w/'non-owned-darwin-1';compat.mkdir(exist_ok=False)
rows=[]
# Real Darwin branch; remove only explicit owned-service test definitions.
for stage in ['host-1','host-2']:
 for row in json.loads((w/stage/'receipt.json').read_text())['units']:
  if row['name'] in ['polyhook-x64Detour','polyhook-ADetour','polyhook-ZydisDisassembler'] and row['exit']==0:
   rows=[r for r in rows if r['name']!=row['name']]+[row]
checks=[]
for row in rows:
 cmd=[x for x in row['command'] if x not in ['-DPLH_OWNED_MEMORY_HOST_TEST','-DPLH_OWNED_MEMORY_ALLOCATOR_TEST']]
 cmd[cmd.index('-o')+1]=str(compat/(row['name']+'.o'))
 cmd[cmd.index('-MF')+1]=str(compat/(row['name']+'.d'))
 p=subprocess.run(cmd,capture_output=True,text=True,timeout=120)
 (compat/(row['name']+'.stdout')).write_text(p.stdout);(compat/(row['name']+'.stderr')).write_text(p.stderr)
 checks.append({'name':row['name'],'command':cmd,'exit':p.returncode,'source':row['source'],'source_sha256':sha(Path(row['source'])),'object':cmd[cmd.index('-o')+1]})
 print('non-owned genuine Darwin compile',row['name'],p.returncode,p.stderr[-500:],flush=True)
assert len(checks)==3 and all(x['exit']==0 for x in checks)
(compat/'receipt.json').write_text(json.dumps({'checks':checks,'source_branches':'Real Darwin Apple x86_64 without either owned test macro; compiled only, not linked/executed','fake_os_macros':False},indent=2)+'\n')
patches=[]
for name in ['x64Detour','ADetour','ZydisDisassembler']:
 old=w/'original/sources'/f'{name}.cpp';new=w/'port/sources'/f'{name}.cpp';patch=w/(name+'.patch')
 patch.write_text(''.join(difflib.unified_diff(old.read_text().splitlines(True),new.read_text().splitlines(True),fromfile=str(old),tofile=str(new))))
 patches.append(patch)
old=w/'original/polyhook2/ZydisDisassembler.hpp';new=w/'include/polyhook2/ZydisDisassembler.hpp';patch=w/'ZydisDisassembler-header.patch';patch.write_text(''.join(difflib.unified_diff(old.read_text().splitlines(True),new.read_text().splitlines(True),fromfile=str(old),tofile=str(new))));patches.append(patch)
units=json.loads((w/'native-1/receipt.json').read_text())['units']
assert all(row['exit']==0 and sha(Path(row['source']))==row['source_sha256'] and sha(Path(row['object']))==row['object_sha256'] for row in units)
production=[row for row in units if row['name']!='fixture']
headers=[w/'include/polyhook2/ZydisDisassembler.hpp',w/'include/polyhook2/OwnedTrampoline.hpp',s/'ue4ss-native-instruction-owned-1/include/polyhook2/Instruction.hpp',s/'ue4ss-native-bounded-owned-1/include/polyhook2/OwnedMemory.hpp']
files=[w/'build.py',w/'link.py',w/'freeze.py',w/'owned_detour.cpp',w/'OwnedTrampoline.cpp',w/'source-provenance.json',*w.glob('original/**/*.cpp'),*w.glob('original/**/*.hpp'),*w.glob('port/sources/*.cpp'),*headers,*patches,w/'link-2/receipt.json',w/'non-owned-darwin-1/receipt.json',*map(lambda x:Path(x['object']),production)]
manifest={'frozen':True,'production_units':production,'replacement_mapping':{'x64Detour.cpp':'native-1/polyhook-x64Detour.o','ADetour.cpp':'native-1/polyhook-ADetour.o','ZydisDisassembler.cpp':'native-1/polyhook-ZydisDisassembler.o'},'additive_object':'native-1/ownedtrampoline.o','do_not_compose':'native-1/fixture.o (fixture main only)','include_priority':[str(s/'ue4ss-native-instruction-owned-1/include'),str(w/'include'),str(s/'ue4ss-native-bounded-owned-1/include'),str(s/'ue4ss-polyhook-platform-port-1/patched/include')],'public_abi':'Original class layouts, fields, vtables and existing signatures unchanged; additive private trampoline helper symbols only. Inline headers require coherent rebuild of identified consumers.','native_scope':'Real SDK compile/link only; no native execution/console contact. All77 undefined linked fixture imports backed by SDK exports.','host_scope':'Real Darwin x86_64 under existing Rosetta route, ASan+UBSan; generated functions owned by genuine default single-map JitRuntime; INPLACE only.','result':receipt['host_result'],'non_native_compatibility':'Real non-owned Darwin branches of all3 changed C++ sources compile without owned test macros. Windows/Linux unchanged branch text retained, with existing portable integer NULL->0 correction; neither OS cross-built here.','limitations':['No PS5 hook execution performed.','No UE4SS default/recommended hook scheme success demonstrated; flattening rejects noncontiguous external holder instructions (VALLOC2).','No concurrent hook/runtime lifetime guarantee.','Pre-patch failure cleanup occurs on x64 destructor.','unHook restoration is not generally transactional; persistent provider refusal or an exception during noexcept base destruction can terminate.','No game/module/remote process reads or hook targets.'],'frozen_files':{str(p):sha(p)for p in files}}
(w/'manifest.json').write_text(json.dumps(manifest,indent=2)+'\n')
(w/'REPORT.md').write_text('''# Genuine owned PolyHook detour experiment\n\nActual Darwin x86_64 execution passed under ASan/UBSan using the existing Rosetta route and genuine AsmJit, AsmTK, Zydis, Zycore and PolyHook sources. Generated source returned42; explicit INPLACE hook returned84; real trampoline returned42; unhook restored42 and revoked the trampoline. A test-only accessor copied a real7-byte prefix through the authoritative owned service before refusing once: hook returnedfalse, all100 original bytes and return42 restored, caller slot cleared, trampoline registration revoked. No fake success/provider or game target was used.\n\nReal PS5 SDK compiled all5 fixture/production translation units and linked the fixture with corrected loader geometry. All77 undefined imports map to actual SDK exports. The PS5 fixture was not executed and no console was contacted. Commands/output and exact input hashes are in link-2/receipt.json; compilation receipts remain separately preserved. Failed link-1 is retained.\n\nProduction composition replaces x64Detour, ADetour and ZydisDisassembler objects and adds OwnedTrampoline. Do not compose fixture main. Include root Instruction overlay first, then this overlay, authoritative bounded-owned service, and the genuine platform headers. Public original class layout/signature ABI is unchanged; private additive helper symbols manage actual owned page lifetime. Root coherently rebuilt both Unreal inline-header consumers.\n\nBefore source patch, the native branch constructs contiguous hook/original bytes and registers both owned source extents. After success it publishes state without allocating/logging. A refused/throwing source write attempts complete original restoration before releasing resources. Failed rollback retains hook/trampoline state and throws; this is not a claim of recovery under persistent provider refusal. The reviewer confirmed the prior partial-patch cleanup defect is addressed for this narrow fixture.\n\nScope is single-thread generated owned mappings and explicit INPLACE. General/default recommended hook schemes are unproven; noncontiguous VALLOC2 holder instructions fail the contiguous check. unHook restoration is not generally transactional, and an exception during noexcept base destruction may terminate. Pre-patch failed resources are reclaimed by x64 destruction. No concurrent lifecycle redesign is claimed.\n\nThe real non-owned Darwin branches of all3 changed C++ sources also compiled with both controlled owned-service definitions absent. Windows/Linux original branches remain in source, apart from prior portable integerNULL-to0 correction, but were not cross-built. Source differences and originals are retained. Historical stage receipts preserve their original emitted build-script hash; final scripts are separately pinned in manifest.json. Production source/object/header hashes match current native-1 and root consolidated-16 inputs.\n''')
print('FROZEN',w/'manifest.json',sha(w/'manifest.json'),flush=True)
